"""Read-only readiness and offline proposed sample for the selected Farouj branch."""
import pathlib,importlib.util,json,copy,datetime,decimal
R=pathlib.Path(__file__).resolve().parents[1];O=pathlib.Path('/private/tmp/finance120');BRANCH='business_1791634772438_p2hlg6w5qii'
def main():
 O.mkdir(mode=0o700,exist_ok=True);sp=importlib.util.spec_from_file_location('c',R/'scripts/capture-financial-readers-63.py');m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m);s=m.session();db=s.resource('dynamodb');cog=s.client('cognito-idp');lam=s.client('lambda');b=db.Table('WhizzMerchants_Businesses').get_item(Key={'businessId':BRANCH},ConsistentRead=True)['Item'];assert b['businessName']=='فروج المدينة' and b['status']=='approved'
 u=cog.list_users(UserPoolId='us-east-1_gtCR3ndzT',Filter='phone_number = "+9647831367435"',Limit=2)['Users'];assert len(u)==1 and u[0]['Enabled'];a={x['Name']:x['Value'] for x in u[0]['Attributes']};assert b['ownerId']==a['sub'] and a['phone_number_verified']=='true'
 c=lam.get_function_configuration(FunctionName='WizzUser-CreateOrder-staging');env=c['Environment']['Variables'];pool=env.get('USER_POOL_ID') or env.get('COGNITO_USER_POOL_ID');u=cog.list_users(UserPoolId=pool,Filter='phone_number = "+9647831367435"',Limit=2)['Users'];assert len(u)==1 and u[0]['Enabled'];customer={x['Name']:x['Value'] for x in u[0]['Attributes']};assert customer['phone_number_verified']=='true'
 pricing=db.Table('staging-PlatformStaff').get_item(Key={'pk':'OPERATIONAL_SETTINGS#DELIVERY_PRICING','sk':'CURRENT'},ConsistentRead=True).get('Item');agreement=None
 if b.get('commercialAgreementId'):agreement=db.Table('staging-MerchantPlatform').get_item(Key={'pk':'COMMERCIAL_AGREEMENT#'+b['commercialAgreementId'],'sk':'CURRENT'},ConsistentRead=True).get('Item')
 p=db.Table('WhizzMerchants_Products').query(IndexName='BusinessIdIndex',KeyConditionExpression='businessId=:b',ExpressionAttributeValues={':b':BRANCH},Limit=100);assert not p.get('LastEvaluatedKey'),'MENU_INVENTORY_INCOMPLETE'
 w=db.Table('staging-Wallets').get_item(Key={'walletId':'WALLET#DRIVER#34d8e408-1021-7076-6055-7325644f97cb','sk':'META'},ConsistentRead=True).get('Item')
 capture={'branch':b,'pricing':pricing,'agreement':agreement,'products':p.get('Items',[]),'customerIdentity':customer,'merchantIdentity':a,'driverWallet':w};f=O/'readiness.private.json';f.write_text(json.dumps(capture,default=lambda v:int(v) if isinstance(v,decimal.Decimal) and v%1==0 else float(v) if isinstance(v,decimal.Decimal) else str(v)));f.chmod(0o600)
 sample=copy.deepcopy(json.loads((R/'frontend/finance-sample-64.json').read_text()));sample.update(kind='PROPOSED_STAGING_SAMPLE',businessId=BRANCH,businessName=b['businessName'],reason='تجهيز فروج المدينة لتجربة النظام المالي الجديد',firstOrderDiscount='NONE');sample['agreement']['id']='FAROUJ_CITY_COD_SAMPLE'
 for family in ['deliveryRules','driverRules']:
  for rule in sample['pricing'][family]:rule['scope']['id']=BRANCH;rule['id']=rule['id'].replace('FATTOUSH','FAROUJ_CITY');rule['effectiveFrom']='2026-10-18T00:00:00.000Z'
 sample['agreement']['values']['effectiveFrom']='2026-10-18T00:00:00.000Z';(R/'docs/farouj-city-proposed-test-settings-120.json').write_text(json.dumps(sample,ensure_ascii=False,indent=2)+'\n')
 def branch_rules(family):return [x.get('id') for x in (pricing or {}).get('values',{}).get(family,[]) if x.get('scope',{}).get('id')==BRANCH]
 result={'part':120,'checkedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'readOnly':True,'branchId':BRANCH,'businessName':b['businessName'],'ownerMatchesSelectedPhone':True,'customerVerified':True,'approvedAgreementLinked':bool(agreement and agreement.get('status')=='ACTIVE'),'deliveryBranchRules':branch_rules('deliveryRules'),'driverBranchRules':branch_rules('driverRules'),'products':[{k:x.get(k) for k in ['productId','name','price','isAvailable','isActive','status']} for x in p.get('Items',[])],'driverAvailable':str((w or {}).get('availableBalance')),'driverLocked':str((w or {}).get('lockedBalance')),'proposedSettingsSavedOnlyLocally':True,'applicationWrites':False};(R/'docs/finance-farouj-readiness-120.json').write_text(json.dumps(result,default=str,ensure_ascii=False,indent=2)+'\n');print(json.dumps(result,default=str,ensure_ascii=False))
